import{_ as t,o as a,c as i,a3 as n,j as e,a as o}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/unterricht-kataloge/kataloge-vermerke-01.png",s="/bilder/unterricht-kataloge/kataloge-vermerke-02.png",b=JSON.parse('{"title":"Vermerkarten im Katalog vorbereiten","description":"","frontmatter":{"title":"Vermerkarten im Katalog vorbereiten","source_pageid":315,"source_revision":5460},"headers":[],"relativePath":"schild3/unterricht-kataloge/vermerk-arten-schulbezogene-kataloge.md","filePath":"schild3/unterricht-kataloge/vermerk-arten-schulbezogene-kataloge.md"}'),d={name:"schild3/unterricht-kataloge/vermerk-arten-schulbezogene-kataloge.md"};function u(g,r,c,h,m,k){return a(),i("div",null,[...r[0]||(r[0]=[n('<h1 id="vermerkarten-im-katalog-vorbereiten" tabindex="-1">Vermerkarten im Katalog vorbereiten <a class="header-anchor" href="#vermerkarten-im-katalog-vorbereiten" aria-label="Permalink to &quot;Vermerkarten im Katalog vorbereiten&quot;">​</a></h1><p>Legen Sie die an Ihrer Schule verwendeten Vermerkarten und ihre Reihenfolge fest. Die eigentlichen Vermerke werden anschließend bei den Schülerdatensätzen erfasst.</p><p><strong>Vermerk-Arten</strong> dienen dazu, Bemerkungen, Eigenschaften, Zugehörigkeiten zu bestimmten Schülergruppen o. ä. in SchILD zu dokumentieren oder zu speichern.</p><p>Die jeweiligen Arten von Vermeken können dabei für die jeweilige Schule <strong>individuell</strong> festgelegt werden, z. B. Versäumnisse von Klassenarbeiten, Ordnungsmaßnahmen, Herkünfte der Schülerinnen und Schüler usw.</p><p>Nach Festlegung der an der Schule verwendeten Vermerk-Arten in diesem Katalog können die jeweiligen Vermerke für die entsprechenden Schülerinnen und Schülern unter <strong>Schüler ➜ Vermerke</strong> zugewiesen bzw. <strong>verwaltet</strong> werden.</p><h2 id="anlegen-neuer-vermerk-arten" tabindex="-1">Anlegen neuer Vermerk-Arten <a class="header-anchor" href="#anlegen-neuer-vermerk-arten" aria-label="Permalink to &quot;Anlegen neuer Vermerk-Arten&quot;">​</a></h2><p><a href="/bilder/unterricht-kataloge/kataloge-vermerke-01.png"><img src="'+l+'" alt="Übersicht über das Fenster Kataloge ➜ Vermerk-Arten." loading="lazy"></a></p><p><em>Übersicht über das Fenster Kataloge ➜ Vermerk-Arten.</em></p><p>Durch Klick auf das &quot;+&quot; kann eine neue Vermerkart <strong>angelegt</strong> werden. In der Spalte &quot;Vermerkart&quot; wird die entsprechende Bezeichnung eingetragen. Die Einträge in der Spalte &quot;Sortierung&quot; sollten nicht manuell verändert werden, da es sonst zu ungewünschten bzw. unerwarteten Sortierungen kommt. Eine individuelle Sortierung wird im nächsten Abschnitt erläutert.</p>',9),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),o("Hinweis")]),e("p",null,"Beachten Sie bei der Anlage von Vermerkarten die geltenden Bestimmungen zum Datenschutz.")],-1),n('<h2 id="sortierung-der-vermerk-arten" tabindex="-1">Sortierung der Vermerk-Arten <a class="header-anchor" href="#sortierung-der-vermerk-arten" aria-label="Permalink to &quot;Sortierung der Vermerk-Arten&quot;">​</a></h2><p>Bei Verwendung der <strong>Sortierung</strong> &quot;Vermerkart&quot; sortiert das Programm alphabetisch, wobei alle Großbuchstaben vor den Kleinbuchstaben einsortiert werden. In dieser Reihenfolge werden die Vermerk-Arten auch in der entsprechenden Auswahl im Programm sortiert.</p><p><a href="/bilder/unterricht-kataloge/kataloge-vermerke-02.png"><img src="'+s+'" alt="Individuelle Sortierung der Vermerk-Arten." loading="lazy"></a></p><p><em>Individuelle Sortierung der Vermerk-Arten.</em></p><p>Ist eine <strong>individuelle Sortierung</strong> gewünscht, so kann dies eingestellt werden. Die Pfeile am linken Rand werden damit aktiviert und erlauben eine individuelle Reihenfolge. Im Beispiel dargestellt ist die Verschiebung der Vermerkart &quot;Ordnungsmaßnahmen&quot;.</p><h2 id="bearbeiten-von-vermerk-arten" tabindex="-1">Bearbeiten von Vermerk-Arten <a class="header-anchor" href="#bearbeiten-von-vermerk-arten" aria-label="Permalink to &quot;Bearbeiten von Vermerk-Arten&quot;">​</a></h2><p>Durch einen Doppelklick in das entsprechende Feld in der Spalte &quot;Vermerkart&quot; kann die Bezeichnung bereits angelegter Vermerk-Arten <strong>geändert</strong> werden.</p><p>Der Haken in der Spalte &quot;Sichtbar&quot; schaltet die Sichtbarkeit in den Auswahlmenüs ein oder aus. Dies bietet sich an, wenn bestimmte Vermerk-Arten nicht in jedem Schuljahr benötigt werden.</p><p>Ein Klick auf das &quot;-&quot; <strong>löscht</strong> die angelegte Vermerkart nach Bestätigung einer Dialogabfrage.</p><h2 id="export-in-eine-excel-tabelle" tabindex="-1">Export in eine Excel-Tabelle <a class="header-anchor" href="#export-in-eine-excel-tabelle" aria-label="Permalink to &quot;Export in eine Excel-Tabelle&quot;">​</a></h2><p>Durch Klick auf &quot;Excel-Export&quot; und &quot;Speichern&quot; im folgenden Fenster kann die aktuelle Ansicht in eine <strong>Excel-Tabelle</strong> exportiert werden.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Vermerk-Arten_(Schulbezogene_Kataloge)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5460.</p>',13)])])}const v=t(d,[["render",u]]);export{b as __pageData,v as default};
